import{_ as n,o as e,c as i,a2 as h}from"./chunks/framework.D3jALGjv.js";const u=JSON.parse('{"title":"🐞 Báo Lỗi & Đề Xuất Tính Năng","description":"","frontmatter":{},"headers":[],"relativePath":"vi/COMMUNITY_SUPPORT.md","filePath":"vi/COMMUNITY_SUPPORT.md"}'),a={name:"vi/COMMUNITY_SUPPORT.md"};function o(r,t,l,g,c,s){return e(),i("div",null,[...t[0]||(t[0]=[h('<h1 id="🐞-bao-loi-đe-xuat-tinh-nang" tabindex="-1">🐞 Báo Lỗi &amp; Đề Xuất Tính Năng <a class="header-anchor" href="#🐞-bao-loi-đe-xuat-tinh-nang" aria-label="Permalink to &quot;🐞 Báo Lỗi &amp; Đề Xuất Tính Năng&quot;">​</a></h1><p>Cảm ơn bạn đã sử dụng <strong>Agent Pilot</strong>. Mọi ý kiến đóng góp hoặc báo cáo lỗi của bạn đều giúp dự án ngày càng hoàn thiện hơn cho cộng đồng.</p><hr><h2 id="🐞-bao-cao-loi-report-bugs-đe-xuat-tinh-nang" tabindex="-1">🐞 Báo Cáo Lỗi (Report Bugs) &amp; Đề Xuất Tính Năng <a class="header-anchor" href="#🐞-bao-cao-loi-report-bugs-đe-xuat-tinh-nang" aria-label="Permalink to &quot;🐞 Báo Cáo Lỗi (Report Bugs) &amp; Đề Xuất Tính Năng&quot;">​</a></h2><p>Nếu trong quá trình sử dụng bạn gặp lỗi kết nối, trình duyệt thao tác chưa chuẩn xác, hoặc gặp vấn đề tương thích với một công cụ AI cụ thể, hãy gửi thông báo để khắc phục kịp thời.</p><h3 id="kenh-tiep-nhan-chinh-thuc" tabindex="-1">Kênh Tiếp Nhận Chính Thức <a class="header-anchor" href="#kenh-tiep-nhan-chinh-thuc" aria-label="Permalink to &quot;Kênh Tiếp Nhận Chính Thức&quot;">​</a></h3><ul><li><strong>Báo cáo lỗi (Bug Report)</strong>: <a href="https://github.com/ducconit/agent-pilot/issues/new" target="_blank" rel="noreferrer">Tạo Issue báo lỗi trên GitHub</a></li><li><strong>Đề xuất tính năng (Feature Request)</strong>: <a href="https://github.com/ducconit/agent-pilot/issues/new" target="_blank" rel="noreferrer">Gửi ý tưởng tính năng mới trên GitHub</a></li><li><strong>Lỗ hổng bảo mật (Security)</strong>: Vui lòng xem hướng dẫn tại <a href="https://github.com/ducconit/agent-pilot/blob/main/SECURITY.md" target="_blank" rel="noreferrer">Chính Sách Bảo Mật (SECURITY.md)</a> trước khi công bố các lỗ hổng nhạy cảm.</li></ul><h3 id="thong-tin-can-cung-cap-khi-bao-loi" tabindex="-1">Thông Tin Cần Cung Cấp Khi Báo Lỗi <a class="header-anchor" href="#thong-tin-can-cung-cap-khi-bao-loi" aria-label="Permalink to &quot;Thông Tin Cần Cung Cấp Khi Báo Lỗi&quot;">​</a></h3><p>Để giúp việc tái hiện và xử lý lỗi diễn ra nhanh nhất, bạn vui lòng đính kèm các thông tin sau:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Hạng mục</th><th style="text-align:left;">Nội dung chi tiết cần mô tả</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Hệ điều hành</strong></td><td style="text-align:left;">Windows 10/11, macOS (Intel / Apple Silicon) hoặc bản phân phối Linux đang dùng</td></tr><tr><td style="text-align:left;"><strong>Phiên bản trình duyệt</strong></td><td style="text-align:left;">Google Chrome, Chromium, Brave hoặc Edge (ví dụ: Chrome 130+)</td></tr><tr><td style="text-align:left;"><strong>Công cụ AI sử dụng</strong></td><td style="text-align:left;">Claude Code, Cursor, Windsurf, Google Antigravity, Cline, OpenCode...</td></tr><tr><td style="text-align:left;"><strong>Phương thức kết nối</strong></td><td style="text-align:left;">Bạn đang kết nối qua <strong>Skills + CLI</strong> hay qua <strong>MCP Server</strong></td></tr><tr><td style="text-align:left;"><strong>Các bước tái hiện lỗi</strong></td><td style="text-align:left;">Câu lệnh prompt đã dùng hoặc trình tự các bước dẫn đến lỗi</td></tr><tr><td style="text-align:left;"><strong>Hình ảnh / Log minh họa</strong></td><td style="text-align:left;">Ảnh chụp màn hình hoặc thông báo lỗi (lưu ý che các thông tin cá nhân nếu có)</td></tr></tbody></table>',10)])])}const p=n(a,[["render",o]]);export{u as __pageData,p as default};
